/// <reference lib="webworker" />

/**
 * The engine worker: loads the engine module and hands it every message.
 *
 * The wasm-bindgen glue is generated by `cargo xtask wasm` and served as an
 * asset next to the module rather than bundled, so building and type-checking
 * the app never need it. It is imported by URL and checked for the two
 * functions this file calls; the messages are typed on the page by the
 * contract types in `./api/` and validated by the engine.
 */

interface EngineHandle {
  handle(message: unknown): Promise<unknown>;
}

interface EngineGlue {
  default(options: { module_or_path: URL }): Promise<unknown>;
  EngineHandle: { start(emit: (message: unknown) => void): Promise<EngineHandle> };
}

const scope = self as unknown as DedicatedWorkerGlobalScope;

// Angular emits workers next to `index.html`, so the assets resolve against
// this script's own URL under any base path.
const assets = new URL('assets/engine/', scope.location.href);

function isGlue(value: unknown): value is EngineGlue {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const init: unknown = Reflect.get(value, 'default');
  const handle: unknown = Reflect.get(value, 'EngineHandle');
  return (
    typeof init === 'function' &&
    typeof handle === 'function' &&
    typeof Reflect.get(handle, 'start') === 'function'
  );
}

async function start(): Promise<EngineHandle> {
  const glue: unknown = await import(/* @vite-ignore */ new URL('engine.js', assets).href);
  if (!isGlue(glue)) {
    throw new Error('the engine glue lacks the functions the worker calls');
  }
  await glue.default({ module_or_path: new URL('engine_bg.wasm', assets) });
  return glue.EngineHandle.start((message) => {
    scope.postMessage(message);
  });
}

const failed = (): void => {
  scope.postMessage({ kind: 'failed' });
};

const engine = start();
engine.catch(failed);

scope.addEventListener('message', (event: MessageEvent<unknown>) => {
  engine.then((handle) => handle.handle(event.data)).catch(failed);
});
